import React from 'react';
import styled from '@emotion/styled';
import { theme } from '../theme';

const Wrapper = styled.div`
  display: flex;
  flex-direction: column;
  height: 100vh;
  height: 100dvh;
  background: ${theme.colors.mainBg};
  font-family: ${theme.typography.fontFamily};
  color: ${theme.colors.mainText};
  overflow: hidden;
`;

const TopBar = styled.header`
  display: flex;
  align-items: center;
  height: 48px;
  background: ${theme.colors.sidebarBg};
  border-bottom: 1px solid ${theme.colors.sidebarBorder};
  padding: 0 ${theme.spacing.lg};
  flex-shrink: 0;
  gap: ${theme.spacing.sm};
  z-index: 100;
`;

const AtlantisLogo = styled.button`
  display: flex;
  align-items: baseline;
  padding: 0;
  background: none;
  border: none;
  cursor: pointer;
  font-family: ${theme.typography.fontFamily};
  font-size: ${theme.typography.fontSizeBase};
  font-weight: 700;
  letter-spacing: -0.02em;
  color: ${theme.colors.mainText};
  flex-shrink: 0;
  transition: opacity 0.15s;
  &:hover { opacity: 0.8; }
  span { color: ${theme.colors.accent}; }
`;

const TitleSep = styled.span`
  color: ${theme.colors.border};
  margin: 0 2px;
  font-weight: 400;
`;

const AppTitle = styled.div`
  font-size: ${theme.typography.fontSizeBase};
  font-weight: 700;
  color: ${theme.colors.mainText};
  letter-spacing: -0.01em;
  flex-shrink: 0;
`;

const AppTitleSub = styled.span`
  font-weight: 400;
  color: ${theme.colors.sidebarTextMuted};
  margin-left: 4px;
  font-size: 12px;
`;

const Spacer = styled.div`
  flex: 1;
`;

interface InspectorLayoutProps {
  title: string;
  subtitle?: string;
  /** Buttons, menus, toggles placed between the spacer and topBarRight */
  actions?: React.ReactNode;
  topBarRight?: React.ReactNode;
  children: React.ReactNode;
}

export function InspectorLayout({ title, subtitle, actions, topBarRight, children }: InspectorLayoutProps) {
  return (
    <Wrapper>
      <TopBar>
        <AtlantisLogo onClick={() => { window.location.hash = '#/home'; }} title="Home">
          Atl<span>antis</span>
        </AtlantisLogo>
        <TitleSep>/</TitleSep>
        <AppTitle>
          {title}
          {subtitle && <AppTitleSub>{subtitle}</AppTitleSub>}
        </AppTitle>
        <Spacer />
        {actions}
        {topBarRight}
      </TopBar>
      {children}
    </Wrapper>
  );
}
